using System.ComponentModel.DataAnnotations;

namespace sv_b2352862ed4047b6ae0d509548c0c740.Models;

public class RegistrationModel
{
    [Required(ErrorMessage = "Attendee name is required.")]
    public string Name { get; set; } = string.Empty;

    [Required(ErrorMessage = "Email is required.")]
    [EmailAddress(ErrorMessage = "Please enter a valid email address.")]
    public string Email { get; set; } = string.Empty;

    [Range(0, 5, ErrorMessage = "Number of guests must be between 0 and 5.")]
    public int NumberOfGuests { get; set; }

    [Required(ErrorMessage = "Please select a preferred session.")]
    public string PreferredSession { get; set; } = string.Empty;

    public string? DietaryRequirements { get; set; }
}

namespace sv_b2352862ed4047b6ae0d509548c0c740.Services;

public class RegistrationService
{
    /// <summary>
    /// Validates the registration against server-side rules.
    /// Returns a dictionary of field name -> error message for any issues found.
    /// </summary>
    public Task<Dictionary<string, string>> ValidateAsync(string email)
    {
        var errors = new Dictionary<string, string>();

        // Simulate checking if the email is already registered
        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors.Add(nameof(Models.RegistrationModel.Email), "This email is already registered.");
        }

        return Task.FromResult(errors);
    }
}

@page "/register"
@rendermode InteractiveServer
@using sv_b2352862ed4047b6ae0d509548c0c740.Models
@inject sv_b2352862ed4047b6ae0d509548c0c740.Services.RegistrationService RegistrationService

<PageTitle>Event Registration</PageTitle>

<h1>Event Registration</h1>

@if (isSubmitted)
{
    <div class="alert alert-success mt-3">
        <strong>Registration successful!</strong> Thank you, @model.Name.
    </div>
}
else
{
    <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="register">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label class="form-label" for="name">Attendee Name</label>
            <InputText id="name" class="form-control" @bind-Value="model.Name" />
            <ValidationMessage For="() => model.Name" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="email">Email</label>
            <InputText id="email" class="form-control" @bind-Value="model.Email" />
            <ValidationMessage For="() => model.Email" />
            @if (!string.IsNullOrEmpty(emailServerError))
            {
                <div class="validation-message">@emailServerError</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label" for="guests">Number of Guests</label>
            <InputNumber id="guests" class="form-control" @bind-Value="model.NumberOfGuests" />
            <ValidationMessage For="() => model.NumberOfGuests" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="session">Preferred Session</label>
            <InputSelect id="session" class="form-select" @bind-Value="model.PreferredSession">
                <option value="">-- Select a session --</option>
                <option value="Morning">Morning</option>
                <option value="Afternoon">Afternoon</option>
                <option value="Evening">Evening</option>
            </InputSelect>
            <ValidationMessage For="() => model.PreferredSession" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="dietary">Special Dietary Requirements</label>
            <InputTextArea id="dietary" class="form-control" @bind-Value="model.DietaryRequirements" />
        </div>

        <button type="submit" class="btn btn-primary">Register</button>
    </EditForm>
}

@code {
    private RegistrationModel model = new();
    private string? emailServerError;
    private bool isSubmitted;

    private async Task HandleSubmit()
    {
        emailServerError = null;

        var serverErrors = await RegistrationService.ValidateAsync(model.Email);

        if (serverErrors.Count > 0)
        {
            if (serverErrors.TryGetValue(nameof(RegistrationModel.Email), out var emailError))
            {
                emailServerError = emailError;
            }
            return;
        }

        isSubmitted = true;
    }
}

